"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7606"],{20342(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel","status":422,"titulo":"A modalidade legal fixa admite altera\xe7\xe3o apenas de descri\xe7\xe3o e base legal"},"descricao":{"codigo":"uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel","requisitos":[],"oQueAconteceu":["A modalidade \xe9 uma das doze do **cat\xe1logo legal fixo** \u2014 as oito cotas da Lei 12.711/2012 (reda\xe7\xe3o da Lei 14.723/2023), a ampla\\nconcorr\xeancia (`AC`) e as tr\xeas a\xe7\xf5es afirmativas institucionais da\\nResolu\xe7\xe3o n\xba 532/2021 (`AC_PCD`, `AC_I` e `AC_Q`) \u2014 e a atualiza\xe7\xe3o tentou mudar um campo al\xe9m de descri\xe7\xe3o\\ne base legal.","Nessas doze, a estrutura de vagas (natureza legal, composi\xe7\xe3o, remanejamento,\\ncrit\xe9rios cumulativos, a\xe7\xe3o no indeferimento) vem da norma que institui a\\nmodalidade \u2014 a lei de cotas ou a resolu\xe7\xe3o do conselho superior \u2014, n\xe3o do\\ncadastro administrativo, e s\xf3 nasce do seed. S\xf3 descri\xe7\xe3o e base legal permanecem\\nedit\xe1veis por cadastro; qualquer diverg\xeancia em outro campo \xe9 recusada antes\\nmesmo de conferir se o valor enviado seria, isoladamente, coerente."],"comoResolver":["Envie a atualiza\xe7\xe3o s\xf3 com descri\xe7\xe3o e/ou base legal. Mudar a estrutura de\\numa modalidade legal fixa exige altera\xe7\xe3o no seed e migra\xe7\xe3o \u2014 o mesmo canal\\nque a criou, n\xe3o o cadastro administrativo."],"ondeAparece":["Atualiza\xe7\xe3o de uma modalidade do cat\xe1logo legal fixo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);